TK_NB("cheatsheet-extract", {"nbformat": 4, "nbformat_minor": 5, "cells": [{"cell_type": "markdown", "source": "# Ekstraksi informasi dan bukti domain\n\nEkstrak apa yang disebut teks beserta bukti. Jangan menyamakan komentar dengan catatan kejadian terverifikasi.\n\nKode lengkap dari pipeline dan snippet asli. Ikuti urutan tahap dan ubah konfigurasi awal sesuai data. Alternatif tersedia pada cheatsheet utama.", "metadata": {}, "id": "cheat-0"}, {"cell_type": "markdown", "metadata": {}, "source": "## Setup & konfigurasi\n\nSatu-satunya sel yang wajib diubah. Tidak butuh label dan tidak butuh GPU, kecuali USE_NER.", "id": "cheat-1"}, {"cell_type": "code", "metadata": {}, "source": "import os\nos.environ.update(HF_HUB_OFFLINE=\"1\", TRANSFORMERS_OFFLINE=\"1\", TOKENIZERS_PARALLELISM=\"false\")\nfrom pathlib import Path\nimport importlib.metadata as md\n\ndef env_report(models_dir=None):\n    import torch\n    for p in (\"torch\", \"transformers\", \"scikit-learn\", \"pandas\", \"numpy\", \"sentence-transformers\", \"lightgbm\"):\n        try:\n            print(p, md.version(p))\n        except md.PackageNotFoundError:\n            print(p, \"TIDAK ADA\")\n    gpu = torch.cuda.is_available()\n    print(\"cuda\", gpu, torch.cuda.get_device_name(0) if gpu else \"\")\n    if gpu:\n        print(\"VRAM GB\", round(torch.cuda.get_device_properties(0).total_memory / 1e9, 1), \"| bf16\", torch.cuda.is_bf16_supported())\n    if models_dir and Path(models_dir).exists():\n        print(\"model lokal:\", sorted(p.name for p in Path(models_dir).iterdir() if p.is_dir()))\n    return gpu\n\nimport os\nimport random\nimport numpy as np\nimport torch\n\ndef seed_everything(seed=42):\n    random.seed(seed); np.random.seed(seed); torch.manual_seed(seed); torch.cuda.manual_seed_all(seed)\n    os.environ[\"PYTHONHASHSEED\"] = str(seed)\n\nimport time\nfrom datetime import datetime\nimport numpy as np\n\nGATES = [(40, \"G1 pilih cabang task\"), (70, \"G2 submission pertama\"), (105, \"G3 lanjut atau lewati BERT\"), (150, \"G4 proyeksi BERT\"), (225, \"G5 blend\"), (240, \"Freeze model\"), (280, \"Unggah final\"), (300, \"Lomba selesai\")]\n_T0 = [time.time()]\n\ndef start_clock(hhmm=None):\n    \"\"\"hhmm='13:00' saat lomba. Tanpa argumen, hitung dari sekarang.\"\"\"\n    if hhmm:\n        h, m = map(int, hhmm.split(\":\"))\n        _T0[0] = datetime.now().replace(hour=h, minute=m, second=0, microsecond=0).timestamp()\n    else:\n        _T0[0] = time.time()\n\ndef clock(label=\"\"):\n    t = (time.time() - _T0[0]) / 60\n    nxt = next((g for g in GATES if g[0] > t), None)\n    print(f\"[T+{t:.0f} menit] {label}\" + (f\" | berikutnya T{nxt[0]}: {nxt[1]}, sisa {nxt[0] - t:.0f} menit\" if nxt else \" | waktu habis\"))\n    return t\n\ndef scale_plan(n_rows, experiments, n_folds, medium=100_000, large=250_000, force=False):\n    \"\"\"Kembalikan (experiments, n_folds) yang aman untuk ukuran data. force=True mematikan pagar.\"\"\"\n    if force or n_rows <= medium:\n        return experiments, n_folds\n    if n_rows <= large:\n        lighter = list(dict.fromkeys((\"tfidf_word\" if v in (\"tfidf_union\", \"tfidf_char\") else v, \"sgd\" if m in (\"svc\", \"svc_cal\", \"rf\", \"mlp\", \"xgb\", \"lgbm\") else m) for v, m in experiments))\n        print(f\"PAGAR SKALA {n_rows} baris: fitur char dibuang, {n_folds} fold jadi 3 -> {lighter}\")\n        return lighter, min(n_folds, 3)\n    plan = [(\"hashing\", \"sgd\"), (\"tfidf_word\", \"sgd\")]\n    print(f\"PAGAR SKALA {n_rows} baris: pakai {plan}, 3 fold. force=True bila yakin RAM dan waktu cukup.\")\n    return plan, min(n_folds, 3)\n\ndef sample_idx(n, k=100_000, seed=42):\n    \"\"\"Indeks acak untuk langkah mahal seperti bootstrap. Bila n <= k, semua baris.\"\"\"\n    return np.arange(n) if n <= k else np.random.default_rng(seed).choice(n, k, replace=False)\n\n# ===== jalankan =====\nimport re, warnings\nimport numpy as np\nimport pandas as pd\nwarnings.filterwarnings(\"ignore\")\nMODELS = Path(os.environ.get(\"COMP_ROOT\", r\"C:\\gemastik\")) / \"models\"\nSEED = 42\nseed_everything(SEED)\nenv_report(MODELS)\n\nDATA, TEXT, TIME, SENTIMENT = \"train.csv\", \"text\", \"time\", None   # SENTIMENT: kolom sentimen bila ada\nISSUES = [\"keamanan_pangan\", \"anggaran\", \"korupsi_tata_kelola\"]   # isu yang dipantau di garis waktu\nFREQ = \"W\"                                       # D, W, atau M\nUSE_NER, NER_MODEL, NER_ROWS = False, MODELS / \"nusabert-ner\", 3000\nGEOJSON = MODELS.parent / \"data_ext/wilayah/idn_adm1.geojson\"\nstart_clock(None)                                # \"13:00\" saat lomba\n", "outputs": [], "execution_count": null, "id": "cheat-2"}, {"cell_type": "markdown", "metadata": {}, "source": "## Muat data\n\nBaca file, otomatis mencoba encoding, simpan parquet.", "id": "cheat-3"}, {"cell_type": "code", "metadata": {}, "source": "from pathlib import Path\nimport pandas as pd\n\ndef read_any(path, cache=True, **kw):\n    \"\"\"df = read_any('train.csv'). Lain kali otomatis membaca train.parquet.\"\"\"\n    p = Path(path)\n    if p.suffix == \".parquet\":\n        return pd.read_parquet(p, **kw)\n    if cache and p.with_suffix(\".parquet\").exists():\n        return pd.read_parquet(p.with_suffix(\".parquet\"))\n    if p.suffix in (\".jsonl\", \".json\"):\n        return pd.read_json(p, lines=p.suffix == \".jsonl\", **kw)\n    if p.suffix in (\".xlsx\", \".xls\"):\n        return pd.read_excel(p, **kw)\n    sep = kw.pop(\"sep\", \"\\t\" if p.suffix == \".tsv\" else \",\")\n    for enc in (\"utf-8\", \"utf-8-sig\", \"latin-1\"):\n        try:\n            df = pd.read_csv(p, sep=sep, encoding=enc, on_bad_lines=\"warn\", **kw)\n            break\n        except UnicodeDecodeError:\n            continue\n    if cache:\n        df.to_parquet(p.with_suffix(\".parquet\"), index=False)\n    return df\n\n# ===== jalankan =====\ndf = read_any(DATA)\nprint(df.shape)\nprint(df.head(3).to_string())\n", "outputs": [], "execution_count": null, "id": "cheat-4"}, {"cell_type": "markdown", "metadata": {}, "source": "## EDA & bahasa\n\nProfil, duplikat, dan porsi 10 bahasa daerah.", "id": "cheat-5"}, {"cell_type": "code", "metadata": {}, "source": "import re\nimport numpy as np\nimport pandas as pd\nfrom sklearn.feature_extraction.text import CountVectorizer, TfidfVectorizer\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import roc_auc_score\nfrom sklearn.model_selection import cross_val_predict\n\ndef _nk(s):\n    return s.fillna(\"\").astype(str).str.lower().str.replace(r\"\\W+\", \" \", regex=True).str.strip()\n\ndef eda_report(train, test=None, text=\"text\", target=None, time=None, n_show=8, sample=20000, seed=42):\n    \"\"\"Kembalikan dict ringkasan berisi saran dan rekomendasi max_words. target: nama kolom atau daftar kolom.\"\"\"\n    tips, out = [], {}\n    print(\"=== PROFIL ===\\ntrain\", train.shape, \"| test\", None if test is None else test.shape)\n    print(pd.DataFrame({\"dtype\": train.dtypes.astype(str), \"null\": train.isna().mean().round(4), \"nunique\": train.nunique()}).to_string())\n    if test is not None:\n        print(\"kolom hanya di train:\", sorted(set(train.columns) - set(test.columns)))\n    tx = train[text].fillna(\"\").astype(str)\n    print(\"\\n=== CONTOH ===\")\n    for t in train[text].sample(min(n_show, len(train)), random_state=seed):\n        print(\" -\", str(t)[:180])\n    key = _nk(train[text])\n    out[\"kosong\"], out[\"duplikat\"] = round(float(key.eq(\"\").mean()), 4), round(float(key.duplicated().mean()), 4)\n    print(\"\\n=== KUALITAS ===\\nkosong\", out[\"kosong\"], \"| duplikat ternormalisasi\", out[\"duplikat\"], \"| punya URL\", round(tx.str.contains(r\"https?://\").mean(), 3),\n          \"| mention\", round(tx.str.contains(r\"@\\w\").mean(), 3), \"| tanda baca akhir kalimat\", round(tx.str.contains(r\"[.!?]\").mean(), 3))\n    print(\"teks paling sering:\", key.value_counts().head(3).to_dict())\n    if out[\"duplikat\"] > .01:\n        tips.append(\"Duplikat > 1%: pakai group fold dan laporkan skor random serta grup.\")\n    w = tx.str.split().str.len()\n    q = w.quantile([.5, .9, .95, .99]).round(0)\n    out[\"max_words\"] = int(q[.95])\n    print(\"\\n=== PANJANG (kata) ===\\n\", q.to_dict(), \"| char p50\", int(tx.str.len().median()))\n    if q[.5] < 5:\n        tips.append(\"Teks sangat pendek: utamakan TF-IDF karakter.\")\n    if q[.95] > 256:\n        tips.append(\"Teks panjang: pertimbangkan head+tail dan chunk.\")\n    if target is not None:\n        print(\"\\n=== TARGET ===\")\n        cols = target if isinstance(target, (list, tuple)) else [target]\n        if len(cols) > 1:\n            Y = train[cols].to_numpy()\n            print(pd.DataFrame({\"pct\": train[cols].mean().round(4)}).T.to_string(), \"\\nlabel per baris\", round(float(Y.sum(1).mean()), 3))\n        else:\n            s = train[cols[0]]\n            if pd.api.types.is_numeric_dtype(s) and s.nunique() > 20:\n                print(s.describe().round(3).to_dict(), \"skew\", round(s.skew(), 3))\n                if s.skew() > 1 and s.min() >= 0:\n                    tips.append(\"Target berekor panjang: latih pada log1p.\")\n            else:\n                vc = s.value_counts(dropna=False)\n                print((vc / len(s)).round(4).to_dict())\n                out[\"rasio_imbalance\"] = round(float(vc.max() / max(vc.min(), 1)), 1)\n                if out[\"rasio_imbalance\"] > 20:\n                    tips.append(\"Imbalance parah: metrik macro-F1/PR-AUC, decision layer dari OOF.\")\n                if s.nunique() <= 50 and s.notna().all():\n                    v = TfidfVectorizer(max_features=30000, min_df=3, sublinear_tf=True)\n                    X = v.fit_transform(tx.iloc[:sample])\n                    m = LogisticRegression(C=4, max_iter=1000).fit(X, s.iloc[:sample].astype(str))\n                    names, coef = v.get_feature_names_out(), m.coef_ if m.coef_.shape[0] > 1 else np.vstack([-m.coef_[0], m.coef_[0]])\n                    print(\"kata khas (cek artefak):\")\n                    for j, c in enumerate(m.classes_):\n                        print(f\"  {c}:\", [names[i] for i in coef[j].argsort()[::-1][:10]])\n    cv = CountVectorizer(token_pattern=r\"(?u)\\b\\w+\\b\", binary=True)\n    X = cv.fit_transform(tx.sample(min(sample, len(tx)), random_state=seed))\n    df_ = np.asarray(X.sum(0)).ravel()\n    print(\"\\n=== KOSAKATA ===\\nvocab\", X.shape[1], \"| kata muncul sekali\", round(float((df_ == 1).mean()), 3))\n    if test is not None and text in test:\n        te = test[text].fillna(\"\").astype(str)\n        vt = CountVectorizer(token_pattern=r\"(?u)\\b\\w+\\b\").fit(te.sample(min(sample, len(te)), random_state=seed))\n        cnt = np.asarray(vt.transform(te.sample(min(sample, len(te)), random_state=seed)).sum(0)).ravel()\n        oov = np.array([x not in cv.vocabulary_ for x in vt.get_feature_names_out()])\n        out[\"oov\"] = round(float(cnt[oov].sum() / max(cnt.sum(), 1)), 3)\n        tk = set(key)\n        out[\"overlap\"] = round(float(_nk(te).isin(tk).mean()), 4)\n        print(\"OOV token test\", out[\"oov\"], \"| teks test ada di train\", out[\"overlap\"])\n        if out[\"oov\"] > .2:\n            tips.append(\"OOV tinggi: TF-IDF karakter atau FastText.\")\n        n = min(5000, len(tx), len(te))\n        t2 = list(tx.sample(n, random_state=seed)) + list(te.sample(n, random_state=seed))\n        lab = np.r_[np.zeros(n), np.ones(n)]\n        Xa = TfidfVectorizer(ngram_range=(1, 2), min_df=2, max_features=100000).fit_transform(t2)\n        out[\"adversarial_auc\"] = round(float(roc_auc_score(lab, cross_val_predict(LogisticRegression(max_iter=500), Xa, lab, cv=3, method=\"predict_proba\")[:, 1])), 4)\n        print(\"AUC adversarial\", out[\"adversarial_auc\"], \"| panjang p50 test\", int(te.str.split().str.len().median()))\n        if out[\"adversarial_auc\"] > .7:\n            tips.append(\"Train dan test berbeda: cek kata pembeda, pertimbangkan split waktu/sumber.\")\n    if time and time in train:\n        t = pd.to_datetime(train[time], errors=\"coerce\")\n        print(\"\\n=== WAKTU ===\\nrentang\", t.min(), \"s.d.\", t.max(), \"| gagal parse\", round(float(t.isna().mean()), 3))\n        if test is not None and time in test:\n            tt = pd.to_datetime(test[time], errors=\"coerce\")\n            print(\"test\", tt.min(), \"s.d.\", tt.max())\n            if tt.min() > t.median():\n                tips.append(\"Test lebih baru dari sebagian besar train: pakai time split.\")\n    out[\"saran\"] = tips\n    print(\"\\n=== SARAN ===\", *(tips or [\"Tidak ada peringatan khusus.\"]), sep=\"\\n - \")\n    return out\n\nimport re\nfrom collections import Counter\nimport numpy as np\nimport pandas as pd\n\n# Kata yang sering di NusaX tiap bahasa dan jarang di korpus Indonesia acuan. Teruji pada NusaX test.\nLANG_MARKERS = {\n    \"jav\": \"lan ing ning kanggo mangan uga nanging akeh panganane panganan dadi saka panggonan mung amarga kene rasane regane wis dhewe rega pelayanane marang uwis panggonane lak sek kuwi utawa panggon maneh luwih kanthi dinggo nganggo yaiku wektu uwong nggawe merga mbengi saiki panggone liyane kutha teka dina ngenteni kaluwarga arep adoh nganti mlebu dingge grapyak dalan awakdewe kanca entuk tuku siji nggarai mesthi mesen iwak suwi sega pithik mrene wengi kowe elek awan resik pemandangane omah njajal meh ben pilian ora ndak ndk mboten nggih ngono ngene awakmu piye durung wes karo ndang pancen ojo sampun panjenengan matur nuwun kulo sopo opo koyo enek duwit sego dewe podo seng lek kon ae wae\",\n    \"sun\": \"sareng teu abdi ieu kanggo oge tiasa tuangeun tuang mung jeung seueur dieu sae dina tos kusabab tempatna upami rasana pikeun eta kuring tuangeunna hoyong deui cekap henteu arurang nyaeta cocog awis sumping wengi pangaos merenah mesen ayeuna sanes janten urang sawaktos rupi-rupi pangaosna sababaraha dinten anjeun teuing sapertos palayanan rerencangan pamandangan kulawargi kitu atawa ngeunah nganggo hayam bade keneh nepi leuwih keur mirah hungkul enggal mimiti kirang disarankeun dugi disayogikeun waktos tina ningali nguciwakeun lebet kedah jalmi tabuh sahiji atuh euy naon kumaha geus moal meni hatur nuhun kieu tong loba siga kunaon\",\n    \"min\": \"untuak lamak indak bana ado tampek wak siko sangaik tampeknyo raso nio makanannyo harago cukuik samo rasonyo urang haragonyo karano juo labiah iko rancak pasan hanyo suko pamandangan biaso palayanan mambuek kaluarga dapek tibo piliahan paliang lua jauah buek ancak sadang masuak taruih sasuai sahinggo gadang baragam wakatu punyo manunggu lamo tajangkau sinan sajuak karajo disajian baliak salain patang mamasan kumuah talampau sanak sambia manuruik liak cubo basamo bantuak babarapo rami pai manikmati lueh apolai naiak mancari goreang direkomendasian dakek\",\n    \"ban\": \"lan sane sajan ajengan ngajeng tiyang jaen nanging krana ten liu jaan tongos wenten tusing lakar utawi puniki sampun dados yening iraga anggon genah ajine ene uli luung dadi punika gen rasane nenten mael becik asane ajenganne tongosne sareng kanti buin ajengane niki suba dugas mesen ento antuk ngaenang lianan indik akeh driki dot peteng timpal ngranayang genahne jani ragane pengarga dina sekadi asapunika ngae anggen dogen teka nganggen kuciwa tiange taen meli makejang kuang bes patuh ngalih kasajiang enggal\",\n    \"bjn\": \"kada gasan ulun banar jua kawa haja wadahnya handak ngini gin tagal haraga pang urang maulah haraganya risturan amun liwar katuju mayan palayanan ngitu cucuk ristu buhan pamandangan mun wayah pina kaluarga matan atawa mambari hawanya wahini sualnya kalu sasuai pian palayanannya labih hanyar babaya tajangkau rami parak hudah bamacam sakalinya imbah talalu mamasan lamahan babarapa tarus suah kadida kadada hancap sangkal pinanya muar malihat mahadang sigar sadang sabarataan rigat intang ikam disuruhakan bujur bubuhan manikmati katujuan jar gonol disurungakan\",\n    \"mad\": \"bik ben engkok ghebey sarah kakanan ngakan riya tape rua mun bede kennengngan polana kiya kakananna rassana deri oreng deddhi terro pole cokop rassa bhei bhegus ongghu bekto diye regghena ghabay bennyak engko' deteng bennya' regghe olle pera' otabe mude lebur bekna senneng lebbi kennengnganna paleng ghuring selaen satiya pelean tadek kodhu kanca jhet settong pade kotta ta' messen korang kia entar bhuru aghebey pelayananna jhek ghik delem masok mare lerres acem-macem kenengngan ajem abit sampe' pendhenan padena lekkas bada\",\n    \"ace\": \"hana ngon mangat lon nyoe pih keu nyan cit meunyo jeuet jih jak lagee watee pajoh mantong teumpat pah lom cukop kamoe ureueng get meuhai rumoh lam uroe saboh leubeh jeut teumpatjih lagak disinoe makananjih boh peunajoh atawa lheueh kon keuneuk rasajih loen leupah saweueb peue paleng ngen trok lee keunoe keuh seubab peulayanan droe sep sagai peuget keuluarga jinoe manok duek sabe phon ngoen inoe 'oh yumjih trep rakan preh peugah baro teungoh bagah tapajoh nakeuh lheuh gureng aneuk\",\n    \"bug\": \"okko sibawa lao ladde' malunra' manre engka anre-anre ellinna aga pole rasana nasaba yako makanja' maneng maega okkoe anroang de' anroanna nasaba' iya' makanja iyaro restorang topa nappa wettu rupanna narekko makessing wenni onroang ladde manyameng anre mancaji makae kanja' iyye melo onroanna iyae pakkanreanna masempo kaminang makkokkoe masoli lunra' massuroang de'na wette malunra makkada maelo jaji tette' pajjamana okkoro laleng yaregga pirasai pakkanreang manu' mancajiwi iyanaritu esso deggaga sedding laingnge cedde' wettunna tennia taue sikenangeng runtu' meloki lettu' lettu\",\n    \"bbc\": \"dohot dang tabo sipanganon jala hian adong inganan alai sian mansai gabe laho godang songon boi mangan naeng argana muse roha holan arga tung mambahen alana daina sahat manang dison parmanganan ikkon ingananna denggan hami akka lomo ima ahu tingki dope ndang borngin jolma dai bagak alani sipanganonna manuhor unang nai mura dalan sipilliton nungga hatop halak dongan uli sude boe panghobasionna lao panatapan marragam somal rap parjolo lambok tuson torus hurang sada iba dao sonang piga-piga menak lam panghobasion\",\n    \"nij\": \"mangat eka tutu penginan diak kuman hong tege angat bahalap tuntang kea awi baya handak rega mawi hetuh hung ije uluh jituh beken amun panginan huang kilau ikei bujur andau dumah due puna hayak hindai wayah gin tame sukup hamalem lalau ewen labih meteh jatunti uras tempayah lime puluh mun haru sadang kawal hapan dinun manuk mengkeme ela kanih jatun intihan capat ampi telu munduk tukep nyerungan itah ikau belai sanang isut sinde pekasak mihup kurik dahang yuh ulih mite\"\n}\nLANG_NAMES = {\"ind\": \"Indonesia/lainnya\", \"jav\": \"Jawa\", \"sun\": \"Sunda\", \"min\": \"Minang\", \"ban\": \"Bali\", \"bjn\": \"Banjar\", \"mad\": \"Madura\", \"ace\": \"Aceh\", \"bug\": \"Bugis\", \"bbc\": \"Batak Toba\", \"nij\": \"Ngaju\"}\n_MARK = {k: set(v.split()) for k, v in LANG_MARKERS.items()}\n\ndef detect_local_language(text, min_hits=2):\n    \"\"\"min_hits=2 menjaga presisi. min_hits=1 untuk batas atas: lebih banyak salah.\"\"\"\n    w = set(re.findall(r\"[a-zà-ÿ'’-]{3,}\", str(text).lower()))\n    best, hits = \"ind\", 0\n    for code, m in _MARK.items():\n        h = len(w & m)\n        if h > hits:\n            best, hits = code, h\n    return best if hits >= min_hits else \"ind\"\n\ndef language_report(texts, show=5, seed=42):\n    \"\"\"Porsi tiap bahasa pada teks unik, batas ketat dan batas longgar, plus contoh untuk dibaca.\"\"\"\n    u = pd.Series(list(texts)).dropna().astype(str).drop_duplicates()\n    strict, loose = u.map(detect_local_language), u.map(lambda t: detect_local_language(t, 1))\n    tbl = pd.DataFrame({\"ketat\": strict.value_counts(), \"longgar\": loose.value_counts()}).fillna(0).astype(int)\n    tbl.index = [LANG_NAMES.get(i, i) for i in tbl.index]\n    tbl[\"ketat_%\"] = (100 * tbl.ketat / len(u)).round(2)\n    tbl[\"longgar_%\"] = (100 * tbl.longgar / len(u)).round(2)\n    local = float((strict != \"ind\").mean())\n    upper = float((loose != \"ind\").mean())\n    print(tbl.sort_values(\"longgar\", ascending=False).to_string())\n    print(f\"Bahasa daerah: {local:.2%} (ketat) sampai {upper:.2%} (longgar) dari {len(u)} teks unik.\")\n    print(\"Saran:\", \"coba NusaBERT dan evaluasi per bahasa.\" if local >= .05 else \"pantau dengan batas longgar; bila di atas 5%, baca sampel lalu coba NusaBERT.\" if upper >= .05 else \"tidak perlu alur khusus; char n-gram cukup.\")\n    hit = u[strict != \"ind\"]\n    for t in hit.sample(min(show, len(hit)), random_state=seed):\n        print(\"  -\", t[:100].replace(\"\\n\", \" \"))\n    return strict.reindex(u.index)\n\n# ===== jalankan =====\nreport = eda_report(df, None, TEXT, time=TIME if TIME in df else None)\n_ = language_report(df[TEXT].sample(min(100000, len(df)), random_state=SEED))\nclock(\"EDA\")\n", "outputs": [], "execution_count": null, "id": "cheat-6"}, {"cell_type": "markdown", "metadata": {}, "source": "## Cleaning: volume asli vs copypasta\n\nTeks identik dihitung sekali untuk peta isu. Laporkan porsi copypasta sebagai temuan.", "id": "cheat-7"}, {"cell_type": "code", "metadata": {}, "source": "import re\nimport numpy as np\nimport pandas as pd\n\n_PSEUDO = {\"\", \"nan\", \"none\", \"null\", \"-\", \"--\", \"n/a\", \"na\", \"[sticker]\"}\n\ndef _groups_minhash(keys, threshold=.8, num_perm=64, shingle=5):\n    from datasketch import MinHash, MinHashLSH\n    lsh, par = MinHashLSH(threshold=threshold, num_perm=num_perm), list(range(len(keys)))\n    def find(x):\n        while par[x] != x:\n            par[x] = par[par[x]]; x = par[x]\n        return x\n    for i, t in enumerate(keys):\n        m = MinHash(num_perm=num_perm)\n        for j in range(max(len(t) - shingle + 1, 1)):\n            m.update(t[j:j + shingle].encode())\n        for k in lsh.query(m):\n            par[find(i)] = find(int(k))\n        lsh.insert(str(i), m)\n    return pd.factorize(np.array([find(i) for i in range(len(keys))]))[0]\n\ndef clean_dataset(df, text=\"text\", target=None, dedup=True, near_dup=False, conflict=None, drop_empty=True, near_threshold=.8):\n    \"\"\"Kembalikan df bersih dengan kolom _group untuk fold. conflict: 'majority', 'drop', atau None.\"\"\"\n    n0 = len(df)\n    df = df.copy()\n    df[text] = df[text].fillna(\"\").astype(str).str.strip()\n    if drop_empty:\n        df = df[~df[text].str.lower().isin(_PSEUDO)]\n    key = df[text].str.lower().str.replace(r\"\\W+\", \" \", regex=True).str.strip()\n    df[\"_group\"] = pd.factorize(key)[0]\n    if near_dup:\n        df[\"_group\"] = _groups_minhash(key.tolist(), near_threshold)\n    n_conf = 0\n    if target is not None and conflict:\n        g = df.groupby(key)[target]\n        bad = g.transform(\"nunique\") > 1\n        n_conf = int(bad.sum())\n        if conflict == \"majority\":\n            df[target] = g.transform(lambda s: s.mode().iloc[0])\n        elif conflict == \"drop\":\n            df, key = df[~bad], key[~bad]\n    if dedup:\n        # Konflik label tetap utuh dan satu grup; tidak memilih label pertama diam-diam.\n        keep = ~pd.DataFrame({'key':key,'target':df[target]}).duplicated() if target is not None and conflict is None else ~key.duplicated()\n        df = df[keep]\n    print(f\"baris {n0} -> {len(df)} | konflik label {n_conf} | grup {df._group.nunique()}\")\n    return df.reset_index(drop=True)\n\ndef clean_test(df, text=\"text\"):\n    \"\"\"Test tidak dibuang: hanya isi kosong.\"\"\"\n    df = df.copy()\n    df[text] = df[text].fillna(\"\").astype(str)\n    return df\n\n# ===== jalankan =====\nd = clean_dataset(df, TEXT).reset_index(drop=True)\nprint(\"baris unik\", len(d), \"| copypasta\", round(1 - len(d) / len(df), 4))\n", "outputs": [], "execution_count": null, "id": "cheat-8"}, {"cell_type": "markdown", "metadata": {}, "source": "## Peta isu dengan kamus\n\nMulti-label. Baca audit dan buang istilah yang salah sasaran: kamus adalah hipotesis.", "id": "cheat-9"}, {"cell_type": "code", "metadata": {}, "source": "import re\nimport ahocorasick\nimport numpy as np\nimport pandas as pd\n\nMBG_ENTITIES = {\n    \"MBG\": [\"mbg\", \"makan bergizi gratis\", \"makan bergizi\", \"makan gratis\", \"makan siang gratis\", \"program makan gratis\", \"embege\"],\n    \"BGN\": [\"bgn\", \"badan gizi nasional\", \"badan gizi\"],\n    \"SPPG\": [\"sppg\", \"satuan pelayanan pemenuhan gizi\", \"dapur mbg\", \"dapur sppg\"],\n    \"Kemenkes\": [\"kemenkes\", \"kementerian kesehatan\", \"menkes\"], \"Kejagung\": [\"kejagung\", \"kejaksaan agung\"], \"KPK\": [\"kpk\"],\n    \"DPR\": [\"dpr\", \"banggar\"], \"JPPI\": [\"jppi\"], \"KPAI\": [\"kpai\"], \"Ombudsman\": [\"ombudsman\"], \"ICW\": [\"icw\"], \"CISDI\": [\"cisdi\"],\n    \"Prabowo\": [\"prabowo\", \"wowo\"], \"Gibran\": [\"gibran\"], \"Sudaryono\": [\"sudaryono\"], \"Dadan Hindayana\": [\"dadan\", \"dadan hindayana\"], \"Nanik Deyang\": [\"nanik\"], \"Purbaya\": [\"purbaya\"],\n}\nMBG_ASPECTS = {\n    \"keamanan_pangan\": [\"keracunan\", \"keracunannya\", \"racun\", \"beracun\", \"basi\", \"busuk\", \"berjamur\", \"jamuran\", \"belatung\", \"ulat\", \"ulet\", \"klb\", \"e coli\", \"salmonella\", \"kadaluarsa\", \"kedaluwarsa\", \"tidak layak\", \"gak layak\", \"ga layak\", \"mual\", \"muntah\", \"diare\", \"pusing\", \"sakit perut\", \"dilarikan\", \"puskesmas\", \"rumah sakit\", \"korban\", \"bau\", \"mentah\"],\n    \"kualitas_menu\": [\"menu\", \"ompreng\", \"ayam\", \"nasi\", \"sayur\", \"susu\", \"burger\", \"spaghetti\", \"spageti\", \"roti\", \"telur\", \"telor\", \"tempe\", \"ikan\", \"kacang\", \"buah\", \"pisang\", \"jeruk\", \"lauk\", \"enak\", \"hambar\", \"porsi\", \"ultra processed\", \"upf\", \"sosis\", \"nugget\"],\n    \"gizi_kesehatan\": [\"gizi\", \"bergizi\", \"ahli gizi\", \"nutrisi\", \"stunting\", \"protein\", \"kalori\", \"akg\", \"obesitas\", \"sehat\", \"kesehatan\", \"dokter\"],\n    \"anggaran\": [\"anggaran\", \"apbn\", \"rapbn\", \"pajak\", \"triliun\", \"pagu\", \"efisiensi\", \"pemborosan\", \"refocusing\", \"dana\", \"buang uang\", \"uang rakyat\", \"biaya\", \"per porsi\", \"15 ribu\", \"10 ribu\", \"10rb\", \"15rb\"],\n    \"korupsi_tata_kelola\": [\"korupsi\", \"koruptor\", \"korup\", \"nepotisme\", \"kolusi\", \"markup\", \"mark up\", \"tersangka\", \"kejagung\", \"jual beli titik\", \"yayasan\", \"calo\", \"transparan\", \"transparansi\", \"proyek\", \"bancakan\", \"berjamaah\", \"kpk\", \"tata kelola\", \"pungli\"],\n    \"distribusi_dapur\": [\"sppg\", \"dapur\", \"distribusi\", \"pengiriman\", \"terlambat\", \"telat\", \"kapasitas\", \"suspend\", \"sanitasi\", \"slhs\", \"sop\", \"relawan\", \"mitra\", \"juknis\", \"ditutup\", \"penerima\", \"belum dapat\", \"tidak merata\", \"gak merata\", \"merata\"],\n    \"pendidikan_guru\": [\"guru\", \"honorer\", \"murid\", \"siswa\", \"sekolah\", \"kantin\", \"santri\", \"pendidikan\", \"gaji guru\", \"biaya sekolah\", \"sekolah gratis\"],\n    \"ekonomi_umkm\": [\"umkm\", \"lapangan kerja\", \"pekerja\", \"pedagang\", \"jualan\", \"catering\", \"katering\", \"petani\", \"peternak\", \"nelayan\", \"susu lokal\"],\n    \"politik\": [\"prabowo\", \"wowo\", \"gibran\", \"dpr\", \"tni\", \"polri\", \"janji kampanye\", \"militer\", \"purbaya\", \"zulhas\", \"sudaryono\", \"nanik\", \"dadan\", \"presiden\", \"pemerintah\", \"menteri\"],\n    \"media_hoaks\": [\"hoax\", \"hoaks\", \"buzzer\", \"influencer\", \"narasi\", \"digoreng\", \"komdigi\", \"klarifikasi\", \"fitnah\"],\n    \"penolakan\": [\"stop\", \"setop\", \"hentikan\", \"bubar\", \"bubarkan\", \"batalkan\", \"hapus\", \"ganti uang\", \"tolak\", \"menolak\"],\n    \"minta_perbaikan\": [\"evaluasi\", \"perbaiki\", \"perbaikan\", \"benahi\", \"awasi\", \"diawasi\", \"pengawasan\", \"tolong\", \"seharusnya\", \"harusnya\"],\n    \"dukungan\": [\"bagus\", \"setuju\", \"mendukung\", \"dukung\", \"program bagus\", \"bermanfaat\", \"terima kasih\", \"makasih\", \"alhamdulillah\", \"lanjutkan\", \"semoga\"],\n}\nMBG_EVENTS = {\"2025-01-06\": \"Peluncuran MBG\", \"2025-09-24\": \"KLB Bandung Barat\", \"2026-06-02\": \"Pimpinan BGN dicopot\", \"2026-07-22\": \"Kepala BGN baru\", \"2026-10-29\": \"Laporan 100 hari\"}\nMBG_FOOD = sorted({w for w in MBG_ASPECTS[\"kualitas_menu\"] if w not in (\"menu\", \"ompreng\", \"enak\", \"hambar\", \"porsi\", \"ultra processed\", \"upf\")})\nMBG_SYMPTOM = [\"mual\", \"muntah\", \"diare\", \"pusing\", \"sakit perut\", \"demam\", \"lemas\"]\nMBG_INCIDENT = [\"keracunan\", \"basi\", \"busuk\", \"berjamur\", \"belatung\", \"ulat\", \"klb\", \"kadaluarsa\", \"kedaluwarsa\"]\n\n_SUFFIX = re.compile(r\"(?:nya|ny|ku|mu|lah|kah)?(?![0-9a-z])\")\n\ndef build_matcher(lex):\n    \"\"\"lex: {kelas: [istilah]}. Kembalikan automaton, dipakai find_terms.\"\"\"\n    a = ahocorasick.Automaton()\n    for key, terms in lex.items():\n        for t in terms:\n            t = t.lower()\n            old = a.get(t) if t in a else (t, [])\n            a.add_word(t, (t, old[1] + [key]))\n    a.make_automaton()\n    return a\n\ndef find_terms(text, matcher):\n    \"\"\"Istilah utuh dalam teks. Akhiran -nya, -ku, -mu ikut cocok: 'menunya' cocok 'menu'.\"\"\"\n    t = str(text).lower()\n    out = []\n    for end, (term, keys) in matcher.iter(t):\n        start = end - len(term) + 1\n        if (start == 0 or not t[start - 1].isalnum()) and _SUFFIX.match(t, end + 1):\n            out.append((term, keys))\n    return out\n\ndef tag_terms(texts, lex=None):\n    \"\"\"DataFrame bool: baris x kelas. Teks identik hanya diproses sekali.\"\"\"\n    lex = lex or MBG_ASPECTS\n    keys, idx = list(lex), {k: i for i, k in enumerate(lex)}\n    m = build_matcher(lex)\n    texts = [\"\" if t is None or t != t else str(t) for t in texts]\n    cache = {}\n    for t in set(texts):\n        row = np.zeros(len(keys), dtype=bool)\n        for _, ks in find_terms(t, m):\n            row[[idx[k] for k in ks]] = True\n        cache[t] = row\n    return pd.DataFrame(np.vstack([cache[t] for t in texts]) if texts else np.zeros((0, len(keys)), bool), columns=keys)\n\ndef term_hits(texts, lex=None):\n    \"\"\"Jumlah baris per istilah. Istilah nol hit dibuang, istilah terlalu sering diaudit.\"\"\"\n    lex = lex or MBG_ASPECTS\n    m = build_matcher(lex)\n    c = {}\n    for t in texts:\n        for term in {x[0] for x in find_terms(t, m)}:\n            c[term] = c.get(term, 0) + 1\n    rows = [(k, t, c.get(t.lower(), 0)) for k, v in lex.items() for t in v]\n    return pd.DataFrame(rows, columns=[\"kelas\", \"istilah\", \"hit\"]).sort_values([\"kelas\", \"hit\"], ascending=[True, False]).reset_index(drop=True)\n\ndef audit_aspects(texts, H, n=30, seed=42):\n    \"\"\"{kelas: contoh acak}. Baca dan hitung presisinya sebelum dipakai di slide.\"\"\"\n    texts = pd.Series(list(texts))\n    return {k: texts[H[k].to_numpy()].drop_duplicates().sample(min(n, int(H[k].sum())), random_state=seed).tolist() for k in H if H[k].any()}\n\ndef aspect_sentiment(H, sentiment):\n    \"\"\"Tabel aspek x sentimen. Satu baris dihitung di semua aspeknya.\"\"\"\n    s = np.asarray(sentiment)\n    return pd.DataFrame({k: pd.Series(s[H[k].to_numpy()]).value_counts() for k in H}).T.fillna(0).astype(int)\n\n# ===== jalankan =====\nH = tag_terms(d[TEXT])\nprint(H.sum().sort_values(ascending=False).to_string())\nhits = term_hits(d[TEXT])\nprint(hits.sort_values(\"hit\", ascending=False).head(25).to_string())\nprint(\"nol hit:\", hits.query(\"hit == 0\").istilah.tolist()[:40])\naudit = audit_aspects(d[TEXT], H, 30)\nfor k in ISSUES:\n    print(\"--\", k, *[t[:90] for t in audit.get(k, [])[:5]], sep=\"\\n   \")\n", "outputs": [], "execution_count": null, "id": "cheat-10"}, {"cell_type": "markdown", "metadata": {}, "source": "## Ekstraksi terstruktur\n\nUang, jumlah, tanggal, makanan, gejala, insiden, entitas. Angka komentar bukan data resmi.", "id": "cheat-11"}, {"cell_type": "code", "metadata": {}, "source": "import re\nfrom functools import lru_cache\nimport pandas as pd\n\n_UNIT = {\"rb\": 1e3, \"ribu\": 1e3, \"k\": 1e3, \"jt\": 1e6, \"juta\": 1e6, \"m\": 1e9, \"miliar\": 1e9, \"milyar\": 1e9, \"t\": 1e12, \"triliun\": 1e12}\nMONEY_RE = re.compile(r\"(?<![\\w.])(rp\\.?\\s*)?(\\d{1,3}(?:[.,]\\d{3})+|\\d+(?:[.,]\\d+)?)\\s*(rb|ribu|k|jt|juta|miliar|milyar|triliun|m|t)?(?![\\w])\", re.I)\nQTY_RE = re.compile(r\"(?<![\\w.])(\\d{1,3}(?:[.,]\\d{3})+|\\d+|puluhan|ratusan|ribuan|belasan)\\s+(siswa|murid|anak|korban|santri|guru|orang|warga|porsi|sekolah|dapur|sppg|penerima)\\b\", re.I)\n_BULAN = \"januari|februari|maret|april|mei|juni|juli|agustus|september|oktober|november|desember|jan|feb|mar|apr|jun|jul|agu|agt|ags|sep|sept|okt|nov|des\"\nDATE_RE = re.compile(rf\"\\b(\\d{{4}}-\\d{{2}}-\\d{{2}}|\\d{{1,2}}[/-]\\d{{1,2}}[/-]\\d{{2,4}}|\\d{{1,2}}\\s+(?:{_BULAN})(?:\\s+\\d{{4}})?|(?:{_BULAN})\\s+\\d{{4}}|kemarin|kemaren|hari ini|tadi pagi|tadi siang|minggu lalu|minggu kemarin|bulan lalu|bulan kemarin|tahun lalu)\\b\", re.I)\n_REL = {\"kemarin\": 1, \"kemaren\": 1, \"hari ini\": 0, \"tadi pagi\": 0, \"tadi siang\": 0, \"minggu lalu\": 7, \"minggu kemarin\": 7, \"bulan lalu\": 30, \"bulan kemarin\": 30, \"tahun lalu\": 365}\n\ndef parse_money(text):\n    \"\"\"Nilai rupiah. Angka tanpa 'Rp' dan tanpa satuan dibuang agar tahun dan jumlah orang tidak ikut.\"\"\"\n    out = []\n    for m in MONEY_RE.finditer(str(text)):\n        rp, num, unit = m.group(1), m.group(2), (m.group(3) or \"\").lower()\n        if not rp and not unit:\n            continue\n        if re.fullmatch(r\"\\d{1,3}(?:[.,]\\d{3})+\", num):\n            val = float(re.sub(r\"[.,]\", \"\", num))\n        else:\n            val = float(num.replace(\",\", \".\"))\n        out.append(val * _UNIT.get(unit, 1))\n    return out\n\ndef parse_quantity(text):\n    return [(m.group(1).lower(), m.group(2).lower()) for m in QTY_RE.finditer(str(text))]\n\n@lru_cache(maxsize=50000)\ndef _resolve(span, base):\n    s = span.lower()\n    b = pd.Timestamp(base) if base else None\n    if s in _REL:\n        return (b - pd.Timedelta(days=_REL[s])).strftime(\"%Y-%m-%d\") if b is not None else None\n    import dateparser\n    cfg = {\"PREFER_DAY_OF_MONTH\": \"first\", \"DATE_ORDER\": \"DMY\"}\n    if b is not None:\n        cfg[\"RELATIVE_BASE\"] = b.to_pydatetime()\n    d = dateparser.parse(span, languages=[\"id\"], settings=cfg)\n    return d.strftime(\"%Y-%m-%d\") if d else None\n\ndef parse_dates(text, base=None):\n    \"\"\"[(teks, YYYY-MM-DD atau None)]. base = waktu posting.\"\"\"\n    return [(m.group(1), _resolve(m.group(1), base)) for m in DATE_RE.finditer(str(text))]\n\ndef extract_records(texts, times=None):\n    \"\"\"Satu baris per dokumen: uang, jumlah, tanggal, makanan, gejala, insiden, entitas.\"\"\"\n    food, symptom, incident, ent = build_matcher({\"x\": MBG_FOOD}), build_matcher({\"x\": MBG_SYMPTOM}), build_matcher({\"x\": MBG_INCIDENT}), build_matcher(MBG_ENTITIES)\n    bases = [None] * len(texts) if times is None else [None if t != t or t is None else pd.to_datetime(t, errors=\"coerce\", utc=True, format=\"mixed\").tz_localize(None).strftime(\"%Y-%m-%d\") if not pd.isna(pd.to_datetime(t, errors=\"coerce\", utc=True, format=\"mixed\")) else None for t in times]\n    rows = []\n    for t, b in zip(texts, bases):\n        t = \"\" if t is None or t != t else str(t)\n        rows.append({\"uang\": parse_money(t), \"jumlah\": parse_quantity(t), \"tanggal\": [d for _, d in parse_dates(t, b) if d],\n                     \"makanan\": sorted({x[0] for x in find_terms(t, food)}), \"gejala\": sorted({x[0] for x in find_terms(t, symptom)}),\n                     \"insiden\": sorted({x[0] for x in find_terms(t, incident)}), \"entitas\": sorted({k for x in find_terms(t, ent) for k in x[1]})})\n    return pd.DataFrame(rows)\n\ndef ner_entities(texts, model_path, batch=32):\n    \"\"\"NER transformer per teks. Pakai pada subset insiden, bukan semua baris.\"\"\"\n    import torch\n    from transformers import pipeline\n    ner = pipeline(\"token-classification\", model=str(model_path), aggregation_strategy=\"simple\", device=0 if torch.cuda.is_available() else -1, batch_size=batch)\n    return [[(e[\"entity_group\"], e[\"word\"]) for e in r] for r in ner([str(t)[:512] for t in texts])]\n\n# ===== jalankan =====\nrec = extract_records(d[TEXT].tolist(), d[TIME].tolist() if TIME in d else None)\nprint({c: int(rec[c].map(len).gt(0).sum()) for c in rec})\nprint(pd.Series([x for r in rec.entitas for x in r]).value_counts().head(12).to_string())\nprint(pd.Series([x for r in rec.makanan for x in r]).value_counts().head(12).to_string())\n", "outputs": [], "execution_count": null, "id": "cheat-12"}, {"cell_type": "markdown", "metadata": {}, "source": "## Lokasi & peta\n\nSebutan lokasi, bukan bukti lokasi kejadian. Saring insiden untuk peta kejadian.", "id": "cheat-13"}, {"cell_type": "code", "metadata": {}, "source": "import re\nfrom pathlib import Path\nimport ahocorasick\nimport numpy as np\nimport pandas as pd\n\nWILAYAH = {\n    \"Aceh\": \"Aceh Barat|Aceh Barat Daya|Aceh Besar|Aceh Jaya|Aceh Selatan|Aceh Singkil|Aceh Tamiang|Aceh Tengah|Aceh Tenggara|Aceh Timur|Aceh Utara|Banda Aceh|Bener Meriah|Bireuen|Gayo Lues|Langsa|Lhokseumawe|Nagan Raya|Pidie|Pidie Jaya|Sabang|Simeulue|Subulussalam\",\n    \"Bali\": \"Badung|Bangli|Buleleng|Denpasar|Gianyar|Jembrana|Karangasem|Klungkung|Tabanan\",\n    \"Banten\": \"Cilegon|Lebak|Pandeglang|Serang|Tangerang|Tangerang Selatan\",\n    \"Bengkulu\": \"Bengkulu|Bengkulu Selatan|Bengkulu Tengah|Bengkulu Utara|Kaur|Kepahiang|Lebong|Mukomuko|Rejang Lebong|Seluma\",\n    \"Daerah Istimewa Yogyakarta\": \"Bantul|Gunungkidul|Kulon Progo|Sleman|Yogyakarta\",\n    \"Daerah Khusus Ibukota Jakarta\": \"Jakarta Barat|Jakarta Pusat|Jakarta Selatan|Jakarta Timur|Jakarta Utara|Kepulauan Seribu\",\n    \"Gorontalo\": \"Boalemo|Bone Bolango|Gorontalo|Gorontalo Utara|Pohuwato\",\n    \"Jambi\": \"Batanghari|Bungo|Jambi|Kerinci|Merangin|Muaro Jambi|Sarolangun|Sungai Penuh|Tanjung Jabung Barat|Tanjung Jabung Timur|Tebo\",\n    \"Jawa Barat\": \"Bandung|Bandung Barat|Banjar|Bekasi|Bogor|Ciamis|Cianjur|Cimahi|Cirebon|Depok|Garut|Indramayu|Karawang|Kuningan|Majalengka|Pangandaran|Purwakarta|Subang|Sukabumi|Sumedang|Tasikmalaya\",\n    \"Jawa Tengah\": \"Banjarnegara|Banyumas|Batang|Blora|Boyolali|Brebes|Cilacap|Demak|Grobogan|Jepara|Karanganyar|Kebumen|Kendal|Klaten|Kudus|Magelang|Pati|Pekalongan|Pemalang|Purbalingga|Purworejo|Rembang|Salatiga|Semarang|Sragen|Sukoharjo|Surakarta|Tegal|Temanggung|Wonogiri|Wonosobo\",\n    \"Jawa Timur\": \"Bangkalan|Banyuwangi|Batu|Blitar|Bojonegoro|Bondowoso|Gresik|Jember|Jombang|Kediri|Lamongan|Lumajang|Madiun|Magetan|Malang|Mojokerto|Nganjuk|Ngawi|Pacitan|Pamekasan|Pasuruan|Ponorogo|Probolinggo|Sampang|Sidoarjo|Situbondo|Sumenep|Surabaya|Trenggalek|Tuban|Tulungagung\",\n    \"Kalimantan Barat\": \"Bengkayang|Kapuas Hulu|Kayong Utara|Ketapang|Kubu Raya|Landak|Melawi|Mempawah|Pontianak|Sambas|Sanggau|Sekadau|Singkawang|Sintang\",\n    \"Kalimantan Selatan\": \"Balangan|Banjar|Banjarbaru|Banjarmasin|Barito Kuala|Hulu Sungai Selatan|Hulu Sungai Tengah|Hulu Sungai Utara|Kotabaru|Tabalong|Tanah Bumbu|Tanah Laut|Tapin\",\n    \"Kalimantan Tengah\": \"Barito Selatan|Barito Timur|Barito Utara|Gunung Mas|Kapuas|Katingan|Kotawaringin Barat|Kotawaringin Timur|Lamandau|Murung Raya|Palangkaraya|Pulang Pisau|Seruyan|Sukamara\",\n    \"Kalimantan Timur\": \"Balikpapan|Berau|Bontang|Kutai Barat|Kutai Kartanegara|Kutai Timur|Mahakam Ulu|Paser|Penajam Paser Utara|Samarinda\",\n    \"Kalimantan Utara\": \"Bulungan|Malinau|Nunukan|Tana Tidung|Tarakan\",\n    \"Kepulauan Bangka Belitung\": \"Bangka|Bangka Barat|Bangka Selatan|Bangka Tengah|Belitung|Belitung Timur|Pangkal Pinang\",\n    \"Kepulauan Riau\": \"Batam|Bintan|Karimun|Kepulauan Anambas|Lingga|Natuna|Tanjung Pinang\",\n    \"Lampung\": \"Bandar Lampung|Lampung Barat|Lampung Selatan|Lampung Tengah|Lampung Timur|Lampung Utara|Mesuji|Metro|Pesawaran|Pesisir Barat|Pringsewu|Tanggamus|Tulang Bawang|Tulang Bawang Barat|Way Kanan\",\n    \"Maluku\": \"Ambon|Buru|Buru Selatan|Kepulauan Aru|Kepulauan Tanimbar|Maluku Barat Daya|Maluku Tengah|Maluku Tenggara|Seram Bagian Barat|Seram Bagian Timur|Tual\",\n    \"Maluku Utara\": \"Halmahera Barat|Halmahera Selatan|Halmahera Tengah|Halmahera Timur|Halmahera Utara|Kepulauan Sula|Pulau Morotai|Pulau Taliabu|Ternate|Tidore Kepulauan\",\n    \"Nusa Tenggara Barat\": \"Bima|Dompu|Lombok Barat|Lombok Tengah|Lombok Timur|Lombok Utara|Mataram|Sumbawa|Sumbawa Barat\",\n    \"Nusa Tenggara Timur\": \"Alor|Belu|Ende|Flores Timur|Kab Timor Tengah Selatan|Kupang|Lembata|Malaka|Manggarai|Manggarai Barat|Manggarai Timur|Nagekeo|Ngada|Rote Ndao|Sabu Raijua|Sikka|Sumba Barat|Sumba Barat Daya|Sumba Tengah|Sumba Timur|Timor Tengah Utara\",\n    \"Papua\": \"Biak Numfor|Jayapura|Keerom|Kepulauan Yapen|Mamberamo Raya|Sarmi|Supiori|Waropen\",\n    \"Papua Barat\": \"Fak Fak|Kaimana|Manokwari|Manokwari Selatan|Pegunungan Arfak|Teluk Bintuni|Teluk Wondama\",\n    \"Papua Barat Daya\": \"Maybrat|Raja Ampat|Sorong|Sorong Selatan|Tambrauw\",\n    \"Papua Pegunungan\": \"Jayawijaya|Kab Pegunungan Bintang|Lanny Jaya|Mamberamo Tengah|Nduga|Tolikara|Yahukimo|Yalimo\",\n    \"Papua Selatan\": \"Asmat|Boven Digoel|Mappi|Merauke\",\n    \"Papua Tengah\": \"Deiyai|Dogiyai|Intan Jaya|Mimika|Nabire|Paniai|Puncak|Puncak Jaya\",\n    \"Riau\": \"Bengkalis|Dumai|Indragiri Hilir|Indragiri Hulu|Kampar|Kepulauan Meranti|Kuantan Singingi|Pekanbaru|Pelalawan|Rokan Hilir|Rokan Hulu|Siak\",\n    \"Sulawesi Barat\": \"Majene|Mamasa|Mamuju|Mamuju Tengah|Pasangkayu|Polewali Mandar\",\n    \"Sulawesi Selatan\": \"Bantaeng|Barru|Bone|Bulukumba|Enrekang|Gowa|Jeneponto|Kepulauan Selayar|Luwu|Luwu Timur|Luwu Utara|Makassar|Maros|Palopo|Pangkajene dan Kepulauan|Parepare|Pinrang|Sidenreng Rappang|Sinjai|Soppeng|Takalar|Tana Toraja|Toraja Utara|Wajo\",\n    \"Sulawesi Tengah\": \"Banggai|Banggai Kepulauan|Banggai Laut|Buol|Donggala|Morowali|Morowali Utara|Palu|Parigi Moutong|Poso|Sigi|Tojo Una Una|Toli-Toli\",\n    \"Sulawesi Tenggara\": \"Bau Bau|Bombana|Buton|Buton Selatan|Buton Tengah|Buton Utara|Kendari|Kolaka|Kolaka Timur|Kolaka Utara|Konawe|Konawe Kepulauan|Konawe Selatan|Konawe Utara|Muna|Muna Barat|Wakatobi\",\n    \"Sulawesi Utara\": \"Bitung|Bolaang Mongondow|Bolaang Mongondow Selatan|Bolaang Mongondow Timur|Bolaang Mongondow Utara|Kep. Siau Tagulandang Biaro|Kepulauan Sangihe|Kepulauan Talaud|Kotamobagu|Manado|Minahasa|Minahasa Selatan|Minahasa Tenggara|Minahasa Utara|Tomohon\",\n    \"Sumatera Barat\": \"Agam|Bukittinggi|Dharmasraya|Kepulauan Mentawai|Lima Puluh Kota|Padang|Padang Panjang|Padang Pariaman|Pariaman|Pasaman|Pasaman Barat|Payakumbuh|Pesisir Selatan|Sawahlunto|Sijunjung|Solok|Solok Selatan|Tanah Datar\",\n    \"Sumatera Selatan\": \"Banyuasin|Empat Lawang|Lahat|Lubuk Linggau|Muara Enim|Musi Banyuasin|Musi Rawas|Musi Rawas Utara|Ogan Ilir|Ogan Komering Ilir|Ogan Komering Ulu|Ogan Komering Ulu Selatan|Ogan Komering Ulu Timur|Pagar Alam|Palembang|Penukal Abab Lematang Ilir|Prabumulih\",\n    \"Sumatera Utara\": \"Asahan|Batu Bara|Binjai|Dairi|Deli Serdang|Gunungsitoli|Humbang Hasundutan|Karo|Labuhanbatu|Labuhanbatu Selatan|Labuhanbatu Utara|Langkat|Mandailing Natal|Medan|Nias|Nias Barat|Nias Selatan|Nias Utara|Padang Lawas|Padang Lawas Utara|Padangsidimpuan|Pakpak Bharat|Pematangsiantar|Samosir|Serdang Bedagai|Sibolga|Simalungun|Tanjungbalai|Tapanuli Selatan|Tapanuli Tengah|Tapanuli Utara|Tebing Tinggi|Toba\"\n}\n# Provinsi tidak punya baris di atas sebagai nama; alias umum di media sosial.\nPROV_ALIAS = {\"Aceh\": \"aceh\", \"Bali\": \"bali\", \"Banten\": \"banten\", \"Daerah Istimewa Yogyakarta\": \"diy|jogja|jogjakarta|yogya|yogyakarta\", \"Daerah Khusus Ibukota Jakarta\": \"dki|jakarta|jkt\",\n              \"Jawa Barat\": \"jawa barat|jabar\", \"Jawa Tengah\": \"jawa tengah|jateng\", \"Jawa Timur\": \"jawa timur|jatim\", \"Kalimantan Barat\": \"kalimantan barat|kalbar\", \"Kalimantan Selatan\": \"kalimantan selatan|kalsel\",\n              \"Kalimantan Tengah\": \"kalimantan tengah|kalteng\", \"Kalimantan Timur\": \"kalimantan timur|kaltim\", \"Kalimantan Utara\": \"kalimantan utara|kaltara\", \"Kepulauan Bangka Belitung\": \"bangka belitung|babel\",\n              \"Kepulauan Riau\": \"kepulauan riau|kepri\", \"Lampung\": \"lampung\", \"Maluku\": \"maluku\", \"Maluku Utara\": \"maluku utara|malut\", \"Nusa Tenggara Barat\": \"nusa tenggara barat|ntb\", \"Nusa Tenggara Timur\": \"nusa tenggara timur|ntt\",\n              \"Papua\": \"papua\", \"Papua Barat\": \"papua barat\", \"Papua Barat Daya\": \"papua barat daya\", \"Papua Pegunungan\": \"papua pegunungan\", \"Papua Selatan\": \"papua selatan\", \"Papua Tengah\": \"papua tengah\", \"Riau\": \"riau\",\n              \"Sulawesi Barat\": \"sulawesi barat|sulbar\", \"Sulawesi Selatan\": \"sulawesi selatan|sulsel\", \"Sulawesi Tengah\": \"sulawesi tengah|sulteng\", \"Sulawesi Tenggara\": \"sulawesi tenggara|sultra\", \"Sulawesi Utara\": \"sulawesi utara|sulut\",\n              \"Sumatera Barat\": \"sumatera barat|sumbar\", \"Sumatera Selatan\": \"sumatera selatan|sumsel\", \"Sumatera Utara\": \"sumatera utara|sumut\", \"Gorontalo\": \"gorontalo\", \"Bengkulu\": \"bengkulu\", \"Jambi\": \"jambi\"}\nKAB_ALIAS = {\"bdg\": \"Bandung\", \"kbb\": \"Bandung Barat\", \"smg\": \"Semarang\", \"solo\": \"Surakarta\", \"mks\": \"Makassar\", \"plg\": \"Palembang\", \"tangsel\": \"Tangerang Selatan\", \"jaksel\": \"Jakarta Selatan\", \"jakbar\": \"Jakarta Barat\", \"jaktim\": \"Jakarta Timur\", \"jakut\": \"Jakarta Utara\", \"jakpus\": \"Jakarta Pusat\"}\n# Nama yang juga kata umum: hanya dihitung bila didahului konteks lokasi.\nAMBIGUOUS = set(\"\"\"padang batu malang serang medan buru sabang merauke bone metro bima ketapang karo kudus puncak batang bangka banjar lebak tegal kediri sampang luwu asmat agam pati kaur alor muna solok landak\nbelu ende rote siak bungo sigi poso dairi balangan tojo gowa deli maros wajo pinrang soppeng barru bantaeng takalar selayar sinjai sidrap tana lingga bintan natuna anambas tolitoli buol parigi morowali konawe kolaka\nsolo ngawi nganjuk sumba flores sikka ngada lembata kupang timor seram tual aru dobo sula tidore ternate halmahera morotai biak nabire mimika paniai dogiyai deiyai yalimo tolikara lanny nduga puncak yahukimo boven mappi\nambon sarmi keerom waropen supiori kaimana fakfak bintuni wondama maybrat tambrauw sorong raja ampat\"\"\".split())\n_CONTEXT = re.compile(r\"(?:\\b(?:di|ke|dari|kab|kabupaten|kota|kec|kecamatan|daerah|wilayah|warga|sppg|sd|smp|sma|smk|sdn|smpn|sman|smkn|mts|man|mi|pemkab|pemkot|bupati|walikota|wali kota)\\s+)$\")\n_KAB = {n.lower(): (n, p) for p, s in WILAYAH.items() for n in s.split(\"|\")}\n_KAB.update({a: _KAB[n.lower()] for a, n in KAB_ALIAS.items() if n.lower() in _KAB})\n_PROV = {a: p for p, s in PROV_ALIAS.items() for a in s.split(\"|\")}\n_AUTO = ahocorasick.Automaton()\nfor _k in set(_KAB) | set(_PROV):\n    _AUTO.add_word(_k, _k)\n_AUTO.make_automaton()\n\ndef find_locations(text):\n    \"\"\"[(kabupaten/kota atau None, provinsi)]. Pencocokan terpanjang: 'bandung barat' mengalahkan 'bandung'.\"\"\"\n    t = str(text).lower()\n    hits = []\n    for end, k in _AUTO.iter(t):\n        s = end - len(k) + 1\n        if (s == 0 or not t[s - 1].isalnum()) and (end + 1 == len(t) or not t[end + 1].isalnum()):\n            hits.append((s, end, k))\n    hits.sort(key=lambda h: (h[0], h[0] - h[1]))\n    out, last = [], -1\n    for s, e, k in sorted(hits, key=lambda h: h[0] - h[1]):\n        if any(not (e < a or s > b) for a, b in [(x[0], x[1]) for x in out]):\n            continue\n        if k in AMBIGUOUS and not _CONTEXT.search(t[max(0, s - 22):s]):\n            continue\n        out.append((s, e, k))\n    res = []\n    for s, e, k in sorted(out):\n        if k in _KAB:\n            res.append(_KAB[k])\n        else:\n            res.append((None, _PROV[k]))\n    return res\n\ndef tag_locations(texts):\n    \"\"\"DataFrame: kab_kota, provinsi (lokasi pertama yang paling spesifik), n_lokasi. Teks identik sekali.\"\"\"\n    texts = [\"\" if t is None or t != t else str(t) for t in texts]\n    cache = {}\n    for t in set(texts):\n        r = find_locations(t)\n        kab = [x for x in r if x[0]]\n        first = kab[0] if kab else r[0] if r else (None, None)\n        cache[t] = (first[0], first[1], len(r))\n    return pd.DataFrame([cache[t] for t in texts], columns=[\"kab_kota\", \"provinsi\", \"n_lokasi\"])\n\ndef resolve_location(name, cutoff=85):\n    \"\"\"Nama dari NER atau kolom metadata ke nama baku, tahan typo. Kembalikan (kab_kota, provinsi, skor).\"\"\"\n    from rapidfuzz import fuzz, process\n    n = re.sub(r\"^(kabupaten|kab\\.?|kota|provinsi|prov\\.?)\\s+\", \"\", str(name).lower().strip())\n    if n in _KAB:\n        return (*_KAB[n], 100.0)\n    if n in _PROV:\n        return (None, _PROV[n], 100.0)\n    m = process.extractOne(n, list(_KAB) + list(_PROV), scorer=fuzz.WRatio, score_cutoff=cutoff)\n    if m is None:\n        return (None, None, 0.0)\n    return (*_KAB[m[0]], float(m[1])) if m[0] in _KAB else (None, _PROV[m[0]], float(m[1]))\n\n# Nama pada geoBoundaries ADM1 (2017, 34 provinsi): empat provinsi Papua baru digabung ke induknya.\n_ADM1 = {\"Bali\": \"Bali\", \"Nusa Tenggara Barat\": \"West Nusa Tenggara\", \"Banten\": \"Banten\", \"Jawa Tengah\": \"Central Java\", \"Jawa Barat\": \"West Java\", \"Kalimantan Tengah\": \"Central Kalimantan\", \"Kalimantan Selatan\": \"South Kalimantan\", \"Kalimantan Barat\": \"West Kalimantan\",\n         \"Sulawesi Tengah\": \"Central Sulawesi\", \"Gorontalo\": \"Gorontalo\", \"Sulawesi Utara\": \"North Sulawesi\", \"Sulawesi Selatan\": \"South Sulawesi\", \"Sulawesi Tenggara\": \"Southeast Sulawesi\", \"Sulawesi Barat\": \"West Sulawesi\", \"Aceh\": \"Aceh\", \"Bengkulu\": \"Bengkulu\", \"Jambi\": \"Jambi\",\n         \"Lampung\": \"Lampung\", \"Riau\": \"Riau\", \"Sumatera Barat\": \"West Sumatra\", \"Sumatera Selatan\": \"South Sumatra\", \"Sumatera Utara\": \"North Sumatra\", \"Nusa Tenggara Timur\": \"East Nusa Tenggara\", \"Maluku\": \"Maluku\", \"Maluku Utara\": \"North Maluku\", \"Jawa Timur\": \"East Java\",\n         \"Kepulauan Bangka Belitung\": \"Bangka-Belitung Islands\", \"Kepulauan Riau\": \"Riau Islands\", \"Papua\": \"Papua\", \"Papua Selatan\": \"Papua\", \"Papua Tengah\": \"Papua\", \"Papua Pegunungan\": \"Papua\", \"Papua Barat\": \"West Papua\", \"Papua Barat Daya\": \"West Papua\",\n         \"Kalimantan Timur\": \"East Kalimantan\", \"Kalimantan Utara\": \"North Kalimantan\", \"Daerah Istimewa Yogyakarta\": \"Special Region of Yogyakarta\", \"Daerah Khusus Ibukota Jakarta\": \"Jakarta Special Capital Region\"}\n\ndef plot_province_map(counts, geojson=None, path=\"peta.png\", title=\"Sebaran per provinsi\"):\n    \"\"\"counts: Series provinsi -> nilai. Tanpa file geojson atau geopandas, otomatis jadi grafik batang.\"\"\"\n    import matplotlib\n    matplotlib.use(\"Agg\")\n    import matplotlib.pyplot as plt\n    s = pd.Series(counts).astype(float)\n    try:\n        if not geojson or not Path(geojson).exists():\n            raise FileNotFoundError(geojson)\n        import geopandas as gpd\n        g = gpd.read_file(geojson)\n        v = s.groupby(s.index.map(lambda p: _ADM1.get(p, p))).sum()\n        g[\"nilai\"] = g.shapeName.map(v).fillna(0)\n        ax = g.plot(column=\"nilai\", cmap=\"YlOrRd\", legend=True, figsize=(11, 4.6), edgecolor=\"#667085\", linewidth=.3)\n        ax.set_axis_off()\n    except Exception as e:\n        print(\"peta dilewati, pakai grafik batang:\", type(e).__name__)\n        t = s.sort_values().tail(20)\n        plt.figure(figsize=(8, max(3, .35 * len(t))))\n        plt.barh(t.index.astype(str), t.values, color=\"#b42318\")\n    plt.title(title)\n    plt.tight_layout(); plt.savefig(path, dpi=160); plt.close()\n    return path\n\n# ===== jalankan =====\nL = tag_locations(d[TEXT])\nprint(\"baris menyebut lokasi:\", round(L.provinsi.notna().mean(), 4))\nprint(L.kab_kota.value_counts().head(15).to_string())\nincident = rec.insiden.map(len).gt(0).to_numpy()\nprov_all = L.provinsi.value_counts()\nprov_inc = L.provinsi[incident].value_counts()\npeta = plot_province_map(prov_inc if len(prov_inc) >= 3 else prov_all, GEOJSON, \"peta.png\", \"Provinsi pada komentar insiden\" if len(prov_inc) >= 3 else \"Provinsi yang disebut\")\n", "outputs": [], "execution_count": null, "id": "cheat-14"}, {"cell_type": "markdown", "metadata": {}, "source": "## NER transformer (opsional)\n\nLewati bila USE_NER=False. Hanya pada baris insiden agar cepat, lalu petakan ke nama baku.", "id": "cheat-15"}, {"cell_type": "code", "metadata": {}, "source": "if USE_NER:\n    idx = np.where(incident)[0][:NER_ROWS]\n    ents = ner_entities(d[TEXT].iloc[idx].tolist(), NER_MODEL)\n    print(pd.Series([e[0] for r in ents for e in r]).value_counts().to_string())\n    locs = [resolve_location(w) for r in ents for g, w in r if g in (\"GPE\", \"LOC\", \"PLACE\", \"LOCATION\", \"FAC\")]\n    print(pd.Series([x[0] for x in locs if x[0]]).value_counts().head(10).to_string())\nelse:\n    print(\"USE_NER=False: pakai gazetteer saja\")\n", "outputs": [], "execution_count": null, "id": "cheat-16"}, {"cell_type": "markdown", "metadata": {}, "source": "## Tren isu & titik perubahan\n\nProporsi per periode, bukan jumlah. Titik perubahan dengan ruptures, kejadian dari MBG_EVENTS.", "id": "cheat-17"}, {"cell_type": "code", "metadata": {}, "source": "import matplotlib\nmatplotlib.use(\"Agg\")\nimport matplotlib.pyplot as plt\nimport numpy as np\nimport pandas as pd\nimport ruptures as rpt\n\ndef _period(times, freq):\n    t = pd.to_datetime(pd.Series(list(times)), errors=\"coerce\", utc=True, format=\"mixed\").dt.tz_localize(None)\n    return t, t.dt.to_period(freq)\n\ndef issue_timeline(times, mask=None, freq=\"W\", min_total=30):\n    \"\"\"Tabel per periode: total, isu, proporsi. Periode di bawah min_total ditandai agar tidak dibaca.\"\"\"\n    t, p = _period(times, freq)\n    m = np.ones(len(t), bool) if mask is None else np.asarray(mask, bool)\n    tl = pd.DataFrame({\"total\": p[t.notna()].value_counts(), \"isu\": p[t.notna() & m].value_counts()}).fillna(0).astype(int).sort_index()\n    tl[\"proporsi\"] = (tl.isu / tl.total).round(4)\n    tl[\"cukup\"] = tl.total >= min_total\n    return tl\n\ndef change_points(tl, col=\"proporsi\", penalty=None, min_size=2):\n    \"\"\"Titik perubahan pada periode yang cukup datanya. Kembalikan daftar periode awal segmen baru.\"\"\"\n    s = tl[tl.cukup][col] if \"cukup\" in tl else tl[col]\n    if len(s) < 2 * min_size + 1:\n        return []\n    x = s.to_numpy(float).reshape(-1, 1)\n    pen = penalty if penalty is not None else 3 * np.log(len(x)) * max(float(np.var(x)), 1e-9)\n    bk = rpt.Pelt(model=\"l2\", min_size=min_size, jump=1).fit(x).predict(pen=pen)\n    return [s.index[i] for i in bk[:-1]]\n\ndef share_over_time(times, labels, freq=\"M\", min_total=30):\n    \"\"\"Proporsi tiap topik per periode. Periode kecil dibuang.\"\"\"\n    t, p = _period(times, freq)\n    ok = t.notna().to_numpy()\n    c = pd.crosstab(p[ok].to_numpy(), np.asarray(labels)[ok])\n    c = c[c.sum(1) >= min_total]\n    return c.div(c.sum(1), axis=0).round(3)\n\ndef plot_issue_timeline(tl, path=\"tren_isu.png\", title=\"Porsi isu per periode\", events=None, cps=None):\n    d = tl[tl.cukup] if \"cukup\" in tl else tl\n    x = d.index.to_timestamp()\n    fig, ax = plt.subplots(figsize=(10, 3.8))\n    ax.bar(x, d.total, width=(x[1] - x[0]) * .8 if len(x) > 1 else 1, color=\"#d0d5dd\")\n    ax.set_ylabel(\"volume\")\n    a2 = ax.twinx()\n    a2.plot(x, d.proporsi, color=\"#b42318\", lw=2)\n    a2.set_ylabel(\"porsi isu\")\n    for c in cps or []:\n        ax.axvline(c.to_timestamp(), color=\"#0f766e\", lw=1.5)\n    for when, name in (events or {}).items():\n        w = pd.Timestamp(when)\n        if len(x) and x[0] <= w <= x[-1]:\n            ax.axvline(w, color=\"#667085\", ls=\"--\", lw=1)\n            ax.text(w, d.total.max(), name, fontsize=8, rotation=90, va=\"top\")\n    ax.set_title(title)\n    plt.tight_layout(); plt.savefig(path, dpi=160); plt.close()\n    return path\n\ndef bertopic_over_time(docs, times, embeddings, nr_bins=12, min_topic_size=30):\n    \"\"\"BERTopic pada embedding yang sudah ada. Pakai sampel 20-50 ribu baris; RAM 500 ribu belum teruji.\"\"\"\n    from bertopic import BERTopic\n    tm = BERTopic(min_topic_size=min_topic_size, calculate_probabilities=False, low_memory=True, verbose=False)\n    tm.fit(docs, embeddings)\n    return tm, tm.topics_over_time(docs, list(pd.to_datetime(pd.Series(list(times)), errors=\"coerce\", utc=True, format=\"mixed\").dt.tz_localize(None)), nr_bins=nr_bins)\n\n# ===== jalankan =====\nimgs = {\"Peta lokasi\": peta}\nif TIME in d:\n    for k in ISSUES:\n        tl = issue_timeline(d[TIME], H[k], FREQ)\n        cps = change_points(tl)\n        print(k, \"titik perubahan:\", [str(c) for c in cps])\n        print(tl[tl.cukup].tail(6).to_string())\n        imgs[\"Tren \" + k] = plot_issue_timeline(tl, f\"tren_{k}.png\", f\"Porsi {k}\", MBG_EVENTS, cps)\n    print(share_over_time(d[TIME], np.where(H.any(axis=1), H.columns[H.to_numpy().argmax(1)], \"lainnya\"), \"M\").tail(6).to_string())\n", "outputs": [], "execution_count": null, "id": "cheat-18"}, {"cell_type": "markdown", "metadata": {}, "source": "## Tabel & bahan slide\n\nSatu baris per dokumen untuk analisis lanjut, plus slide. Data tidak boleh keluar: masukkan selagi lomba berjalan.", "id": "cheat-19"}, {"cell_type": "code", "metadata": {}, "source": "import matplotlib\nmatplotlib.use(\"Agg\")\nimport matplotlib.pyplot as plt\nimport numpy as np\nimport pandas as pd\nimport seaborn as sns\nfrom sklearn.metrics import confusion_matrix\n\ndef _save(path):\n    plt.tight_layout(); plt.savefig(path, dpi=160); plt.close()\n    return path\n\ndef plot_heatmap(table, path=\"heatmap.png\", title=\"Aspek x sentimen\", fmt=\".0f\", normalize=False):\n    t = table.div(table.sum(1), axis=0) if normalize else table\n    plt.figure(figsize=(8, max(3, .4 * len(t))))\n    sns.heatmap(t, annot=True, fmt=\".2f\" if normalize else fmt, cmap=\"YlGnBu\", cbar=False)\n    plt.title(title)\n    return _save(path)\n\ndef plot_confusion(y, pred, names=None, path=\"confusion.png\"):\n    c = confusion_matrix(y, pred, normalize=\"true\")\n    return plot_heatmap(pd.DataFrame(c, index=names, columns=names), path, \"Confusion matrix (per baris)\", fmt=\".2f\")\n\ndef plot_timeline(ts, path=\"timeline.png\", events=None, freq=\"W\", title=\"Volume per minggu\"):\n    \"\"\"events: {'YYYY-MM-DD': 'nama kejadian'}\"\"\"\n    t = pd.to_datetime(pd.Series(list(ts)), errors=\"coerce\").dropna()\n    v = t.dt.to_period(freq).value_counts().sort_index()\n    x = v.index.to_timestamp()\n    plt.figure(figsize=(10, 3.6)); plt.plot(x, v.values, color=\"#0f766e\")\n    for d, name in (events or {}).items():\n        plt.axvline(pd.Timestamp(d), color=\"#b42318\", ls=\"--\", lw=1); plt.text(pd.Timestamp(d), v.max(), name, fontsize=8, rotation=90, va=\"top\")\n    plt.title(title)\n    return _save(path)\n\ndef plot_bars(series, path=\"bars.png\", title=\"Distribusi\", top=20):\n    s = pd.Series(series).sort_values().tail(top)\n    plt.figure(figsize=(8, max(3, .35 * len(s)))); plt.barh(s.index.astype(str), s.values, color=\"#0f766e\"); plt.title(title)\n    return _save(path)\n\nfrom pptx import Presentation\nfrom pptx.util import Inches, Pt\n\ndef build_slides(slides, out=\"hasil.pptx\", template=None):\n    \"\"\"slides: list dict {title, bullets, image}. Satu slide per dict.\"\"\"\n    prs = Presentation(template) if template else Presentation()\n    for s in slides:\n        sl = prs.slides.add_slide(prs.slide_layouts[1])\n        sl.shapes.title.text = s.get(\"title\", \"\")\n        body = sl.placeholders[1].text_frame\n        body.clear()\n        for i, b in enumerate(s.get(\"bullets\", [])):\n            p = body.paragraphs[0] if i == 0 else body.add_paragraph()\n            p.text = str(b); p.font.size = Pt(20)\n        if s.get(\"image\"):\n            sl.shapes.add_picture(s[\"image\"], Inches(.6), Inches(3.2), height=Inches(3.8))\n    prs.save(out)\n    return out\n\n# ===== jalankan =====\nout = pd.concat([d[[TEXT]], L[[\"kab_kota\", \"provinsi\"]], rec, H.add_prefix(\"isu_\")], axis=1)\nout.astype({c: str for c in rec.columns}).to_parquet(\"hasil_ekstraksi.parquet\", index=False)\nif SENTIMENT and SENTIMENT in d:\n    imgs[\"Aspek x sentimen\"] = plot_heatmap(aspect_sentiment(H, d[SENTIMENT].astype(str).to_numpy()), \"aspek_sentimen.png\", normalize=True)\nimgs[\"Peta isu\"] = plot_bars(H.sum(), \"isu.png\", \"Jumlah baris unik per isu\")\nbuild_slides([{\"title\": k, \"bullets\": [f\"{len(d)} baris unik dari {len(df)}\"], \"image\": v} for k, v in imgs.items()], \"bahan_slide.pptx\")\nprint(out.shape, list(imgs.values()))\nclock(\"selesai\")\n", "outputs": [], "execution_count": null, "id": "cheat-20"}], "metadata": {"kernelspec": {"name": "python3", "display_name": "Python 3", "language": "python"}, "toolkit": {"title": "Ekstraksi informasi dan bukti domain · cheatsheet", "tasks": ["mbg_extract"], "kind": "cheatsheet", "cards": ["pipeline:extract:setup", "pipeline:extract:load", "pipeline:extract:eda", "pipeline:extract:clean", "pipeline:extract:tag", "pipeline:extract:extract", "pipeline:extract:geo", "pipeline:extract:ner", "pipeline:extract:trend", "pipeline:extract:insight"]}}});
